package com.vahotel.web;
import com.vahotel.model.*;import com.vahotel.repo.AccountRepository;import com.vahotel.service.OtpService;import jakarta.servlet.http.HttpSession;import java.nio.file.*;import java.util.UUID;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@Controller public class RegistrationController {private static final java.util.regex.Pattern PERSON_NAME=java.util.regex.Pattern.compile("[\\p{L}\\p{M}]+(?:[ '\u2019.-][\\p{L}\\p{M}]+)*");private final AccountRepository accounts;private final PasswordEncoder encoder;private final OtpService otp;private final com.vahotel.service.EmailNotificationService email;@Value("${va.hotel.identity.storage:./data/identity-documents}") private String storage;
 public RegistrationController(AccountRepository a,PasswordEncoder e,OtpService o,com.vahotel.service.EmailNotificationService email){accounts=a;encoder=e;otp=o;this.email=email;}
 @GetMapping("/register") public String form(@RequestParam(defaultValue="false") boolean edit,HttpSession session,Model m){m.addAttribute("captchaEnforced",false);if(edit){m.addAttribute("firstName",session.getAttribute("pendingFirstName"));m.addAttribute("surname",session.getAttribute("pendingSurname"));m.addAttribute("email",session.getAttribute("pendingEmail"));m.addAttribute("editingSignup",true);}return "register";}
 @PostMapping("/register") public String register(@RequestParam String firstName,@RequestParam String surname,@RequestParam String email,@RequestParam String password,HttpSession session,Model m){firstName=firstName.trim();surname=surname.trim();email=email.trim();m.addAttribute("firstName",firstName);m.addAttribute("surname",surname);m.addAttribute("email",email);if(!validPersonName(firstName)||!validPersonName(surname)){m.addAttribute("error","First name and surname may contain letters, spaces, apostrophes, and hyphens only. Numbers are not allowed.");return "register";}email=email.toLowerCase();if(accounts.findByEmail(email).isPresent()){m.addAttribute("error","Email is already registered.");return "register";}if(!password.matches("(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[^A-Za-z0-9]).{10,}")||password.chars().anyMatch(Character::isWhitespace)){m.addAttribute("error","Password must be 10+ characters with uppercase, lowercase, number and special character, without spaces.");return "register";}session.setAttribute("pendingName",firstName+" "+surname);session.setAttribute("pendingFirstName",firstName);session.setAttribute("pendingSurname",surname);session.setAttribute("pendingEmail",email);session.setAttribute("pendingPassword",encoder.encode(password));session.setAttribute("otpEmailed",otp.send(email));return "redirect:/verify-email";}
 private boolean validPersonName(String name){return name!=null&&name.length()<=60&&PERSON_NAME.matcher(name).matches();}
 @GetMapping("/verify-email") public String verifyPage(HttpSession s,Model m){if(s.getAttribute("pendingEmail")==null)return "redirect:/register";addOtpNotice(s,m);return "verify-email";}
 @PostMapping("/verify-email") public String verify(@RequestParam String code,HttpSession s,Model m){String email=(String)s.getAttribute("pendingEmail");if(email==null)return "redirect:/register";if(!otp.verify(email,code)){m.addAttribute("error","Code is invalid or expired.");addOtpNotice(s,m);return "verify-email";}Account a=new Account(email,(String)s.getAttribute("pendingPassword"),(String)s.getAttribute("pendingName"),Role.CUSTOMER,false);a.setEmailVerified(true);accounts.save(a);s.setAttribute("identityEmail",email);s.removeAttribute("pendingEmail");s.removeAttribute("pendingPassword");s.removeAttribute("pendingName");s.removeAttribute("pendingFirstName");s.removeAttribute("pendingSurname");s.removeAttribute("otpEmailed");return "redirect:/identity";}
 private void addOtpNotice(HttpSession session,Model model){Boolean sent=(Boolean)session.getAttribute("otpEmailed");model.addAttribute("deliveryNotice",Boolean.TRUE.equals(sent)?"Verification code sent to your email. It expires in 10 minutes.":"Email was unavailable. For this local demo, check the application terminal for the verification code.");}
 @GetMapping("/identity") public String identity(HttpSession s){return s.getAttribute("identityEmail")==null?"redirect:/register":"identity";}
 @PostMapping("/identity") public String identityUpload(@RequestParam MultipartFile document,HttpSession s,Model m){String email=(String)s.getAttribute("identityEmail");if(email==null)return "redirect:/register";if(document.isEmpty()||document.getSize()>5*1024*1024){m.addAttribute("error","Upload a non-empty file up to 5 MB.");return "identity";}String type=document.getContentType();if(type==null||!java.util.Set.of("image/jpeg","image/png","application/pdf").contains(type)){m.addAttribute("error","Only JPG, PNG, and PDF files are accepted.");return "identity";}try{Path dir=Path.of(storage).toAbsolutePath().normalize();Files.createDirectories(dir);String ext=type.equals("application/pdf")?".pdf":type.equals("image/png")?".png":".jpg";String filename=UUID.randomUUID()+ext;Path dest=dir.resolve(filename).normalize();if(!dest.startsWith(dir))throw new IllegalArgumentException("Invalid file path");document.transferTo(dest);Account a=accounts.findByEmail(email).orElseThrow();a.setIdentityDocumentPath(dest.toString());accounts.save(a);this.email.sendRegistrationSubmitted(a);s.setAttribute("registrationPendingDashboardEmail",email);s.removeAttribute("identityEmail");return "redirect:/customer/dashboard";}catch(Exception e){m.addAttribute("error","Unable to save the identity document.");return "identity";}}
}
